  return h.button(
    [
      h.Type("button"),
      h.DataAttribute("slot", "sidebar-group-action"),
      h.DataAttribute("sidebar", "group-action"),
      h.AriaLabel(label),
      h.Class(cn(sidebarGroupActionClasses, className)),
      ...(onClick === undefined ? [] : [h.OnClick(onClick)]),
