      h.AriaLabel("Toggle Sidebar"),
      h.Title("Toggle Sidebar"),
      h.DataAttribute("slot", "sidebar-rail"),
      h.DataAttribute("sidebar", "rail"),
      h.DataAttribute("side", side),
      h.Class(sidebarRailClasses),
      ...(onClick === undefined ? [] : [h.OnClick(onClick)]),
    ],
    []
  );
};

